-- 1116: Blog post -- "Microsoft Certified Azure AI Engineer Associate (AI-102) in Singapore:
--       WSQ Funding, Exam Guide and Career Path"
--       Lead-magnet post for the WSQ AI-102 course (TGS-2023036651): what the certification
--       covers, AI-900 vs AI-102, the six course topics, the Singapore market case, and the
--       full WSQ funding breakdown. Backdated to 2025-12-09 (published, status 1) per admin
--       request; LinkedIn share suppressed via the linkedin_urn sentinel.
--
-- Notes for future editors:
--  * apply.php splits statements on ";" at end-of-line -- the content HTML below is ONE line.
--  * Idempotent: WHERE NOT EXISTS on url_key, INSERT IGNORE on tag links. Safe to re-run.
--  * SG-only guard via @mms_instance -- the CTA course is SG WSQ, absent on MY/GH.
--  * All CTA targets verified HTTP 200 before writing (course page, AI-900, AZ-900, AI-103,
--    Azure exam-prep category, practice-exam portal + its AI-900 exam).
--  * NOTE: the practice-exam portal has NO AI-102 exam (only AI-900 in the Azure AI line), so
--    the post links the portal index + AI-900 and never claims an AI-102 practice exam exists.
--  * The two SkillsFuture government portals (gobusiness / myskillsfuture) 403 to curl behind
--    their WAF, so they are deliberately NOT linked in the body -- the course page links them.
--  * Content is pure ASCII (no em-dashes/curly quotes) so apply.php's utf8 connection is safe.
--  * hero_image_url is NOT set here (SQL cannot render one) -- generate on prod post-deploy,
--    then bake the R2 URL back in a follow-up migration (see 1110 for the pattern).
--    Hero theme dry-run: title resolves to 'funding' (kw: funding) -> sky/badge motif. Correct.

SET @is_sg := IF(@mms_instance = 'SG', 1, 0);

INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `linkedin_urn`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'Microsoft Certified Azure AI Engineer Associate (AI-102) in Singapore: WSQ Funding, Exam Guide and Career Path', 'azure-ai-engineer-associate-ai-102-certification-singapore', 'Every company now wants to ship AI features, and very few have engineers who can actually build them on a governed cloud platform. Microsoft''s AI-102 is the certification that proves you can. Here is what the Azure AI Engineer Associate credential covers, how WSQ funding brings the 2-day course down to $351 nett for eligible Singaporeans, and how to prepare for the exam.', '<p>Every board in Singapore has asked the same question in the last eighteen months: <em>what are we doing about AI?</em> The answer usually arrives as a pilot &mdash; a chatbot over the policy library, a document extractor for claims, a search box that finally understands what people mean. Then someone has to actually build it, secure it, keep it inside the company''s data boundary, and pay for it predictably. That person is an <strong>Azure AI engineer</strong>, and <strong>Microsoft''s AI-102 exam</strong> is the credential that proves the job is in safe hands.</p> <p><strong>Short version:</strong> AI-102 (Microsoft Certified: Azure AI Engineer Associate) validates that you can design and implement AI solutions using Azure AI services &mdash; vision, language, knowledge mining, document intelligence and Azure OpenAI. It is the role-based associate certification for people who <em>build</em> AI, not just use it. In Singapore, the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-azure-ai-engineer-associate-ai-102-training.html">2-day WSQ AI-102 training course</a> is priced at $900, and eligible Singaporeans aged 40 and above pay <strong>$351 nett after up to 70% WSQ funding</strong> &mdash; with SkillsFuture Credit claimable on the balance.</p> <h2>Why AI-102 is a different kind of AI certification</h2> <p>The market is flooded with AI courses that teach you to write better prompts. Useful, but not scarce. What is scarce is the engineer who can take a working prototype and turn it into something a regulated company will actually deploy: authenticated, monitored, cost-controlled, and running against corporate data without leaking it.</p> <p>That is the gap AI-102 targets. It is an <strong>associate-level, role-based</strong> certification, which in Microsoft''s taxonomy means it assumes real hands-on ability rather than conceptual awareness. Compare the two Azure AI certifications side by side:</p> <table> <thead> <tr><th>&nbsp;</th><th>AI-900 (Fundamentals)</th><th>AI-102 (Engineer Associate)</th></tr> </thead> <tbody> <tr><td><strong>Level</strong></td><td>Fundamentals</td><td>Associate (role-based)</td></tr> <tr><td><strong>Audience</strong></td><td>Business, sales, managers, career switchers</td><td>Developers, data engineers, solution architects</td></tr> <tr><td><strong>Proves you can</strong></td><td>Describe AI workloads and Azure AI services</td><td>Build, secure and deploy AI solutions on Azure</td></tr> <tr><td><strong>Coding required</strong></td><td>None</td><td>Yes &mdash; Python or C#, plus REST/SDK calls</td></tr> <tr><td><strong>Typical next step</strong></td><td>AI-102</td><td>Specialist / architect tracks</td></tr> </tbody> </table> <p>If you have never touched Azure, start with the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-ai-fundamentals-ai-900.html">WSQ Microsoft Azure AI Fundamentals (AI-900)</a> course or the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-fundamentals-az-900.html">WSQ Microsoft Azure Fundamentals (AZ-900)</a> course first &mdash; both are also WSQ funded. If you already write code and want the credential that gets you onto AI delivery work, AI-102 is the one to sit.</p> <h2>What the AI-102 exam actually covers</h2> <p>Microsoft revised AI-102 substantially as generative AI moved from novelty to default. The current exam is weighted toward Azure OpenAI and knowledge mining rather than the classic vision-and-speech services that dominated earlier versions. The <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-azure-ai-engineer-associate-ai-102-training.html">WSQ AI-102 course</a> is built around six practical topics mapped to that scope:</p> <ol> <li><strong>Get started with Azure AI Services</strong> &mdash; provisioning, keys and endpoints, authentication, containers, and the responsible-AI controls you are expected to configure rather than merely acknowledge.</li> <li><strong>Create computer vision solutions with Azure AI Vision</strong> &mdash; image analysis, OCR, and custom vision models for classification and object detection.</li> <li><strong>Develop natural language processing solutions</strong> &mdash; language understanding, entity and sentiment extraction, translation, and conversational language understanding.</li> <li><strong>Implement knowledge mining with Azure AI Search</strong> &mdash; indexers, skillsets, and the vector search that underpins every serious retrieval-augmented generation (RAG) build.</li> <li><strong>Develop solutions with Azure AI Document Intelligence</strong> &mdash; prebuilt and custom models for invoices, receipts, forms and identity documents. This is where most Singapore back-office automation projects actually start.</li> <li><strong>Develop generative AI solutions with Azure OpenAI Service</strong> &mdash; deploying models, prompt engineering in code, grounding responses on your own data, and applying content filters.</li> </ol> <p>Two things worth flagging for exam candidates. First, <strong>the exam expects code</strong>. You will see SDK snippets in Python and C# and be asked which call, parameter or ordering is correct &mdash; memorising service names is not enough. Second, <strong>Azure AI Search is heavily weighted</strong> because it is the backbone of grounding an LLM on corporate documents; if your revision time is limited, spend it there and on Azure OpenAI rather than on the speech services.</p> <h2>The learning outcomes, in plain terms</h2> <p>The WSQ course is assessed against three competency outcomes, which are worth reading as a description of what the job involves:</p> <ul> <li><strong>Analyse algorithms</strong> in Azure AI applications and relate them to efficiency &mdash; knowing not just that a service exists, but what it costs in latency and dollars at volume.</li> <li><strong>Evaluate the strengths and limitations</strong> of the different Azure AI services &mdash; choosing Document Intelligence over a general vision model, or a hybrid vector-plus-keyword search over pure semantic search, and being able to justify it.</li> <li><strong>Assess feasibility and improvements</strong> when applying Azure AI to product and maintenance processes &mdash; the part that separates a demo from something operations will support.</li> </ul> <h2>Who should sit AI-102</h2> <p>Look for one of these situations in your own work:</p> <ul> <li>You are a <strong>developer</strong> whose team has been handed an AI feature and no clear architecture for it.</li> <li>You are a <strong>data or platform engineer</strong> already on Azure, and RAG pipelines are landing on your plate.</li> <li>You are a <strong>solution architect or tech lead</strong> who must review AI designs credibly rather than take a vendor''s word for them.</li> <li>You are <strong>switching into AI delivery</strong> from a general software role and need a credential a hiring manager recognises.</li> </ul> <p>The practical prerequisite is programming ability in Python or C# and some familiarity with Azure and REST APIs. You do not need a machine-learning background &mdash; AI-102 is about <em>consuming and engineering with</em> AI services, not training models from scratch. If model building is what you want, that is the data-scientist track instead.</p> <h2>What it is worth in the Singapore market</h2> <p>Two forces make this credential unusually well-timed here. Singapore''s National AI Strategy 2.0 commits to tripling the AI practitioner pool to roughly 15,000, and public-sector and financial-services buyers overwhelmingly deploy on governed cloud platforms &mdash; which in most enterprises means Azure, because that is where the Microsoft 365 estate already lives. The demand is not for people who can describe AI. It is for people who can ship it against a compliance review.</p> <p>Azure AI engineering roles in Singapore typically sit in the same band as senior cloud and data engineering roles, and the certification does a specific job in the hiring process: it gets a career-switcher''s CV past the screen. For an employer, an associate-level Microsoft badge is a defensible signal that the person has hands-on ability, which matters more when your last three years of experience are in a different specialisation.</p> <h2>WSQ funding: what you actually pay</h2> <p>This is where the Singapore-specific advantage is significant. The AI-102 course is WSQ funded under the SkillsFuture Singapore framework, so the fee you pay depends on your profile:</p> <table> <thead> <tr><th>Learner profile</th><th>Funding</th><th>Nett fee (before GST)</th></tr> </thead> <tbody> <tr><td>Full course fee</td><td>&mdash;</td><td>$900</td></tr> <tr><td>Singaporean below 40 / Singapore PR</td><td>50%</td><td><strong>$450</strong></td></tr> <tr><td>Singaporean aged 40 and above (MCES)</td><td>70%</td><td><strong>$270</strong></td></tr> <tr><td>SME-sponsored (Singaporean/PR direct hire)</td><td>70%</td><td><strong>$270</strong></td></tr> </tbody> </table> <p>With GST applied on the full course fee as required for funded courses, the baseline nett payable works out to <strong>$531</strong>, and the MCES / SME nett to <strong>$351</strong>. Three further offsets stack on top of that:</p> <ul> <li><strong>SkillsFuture Credit</strong> &mdash; Singaporeans aged 25 and above can apply their credit against the remaining out-of-pocket fee, which can bring it close to zero.</li> <li><strong>SkillsFuture Enterprise Credit (SFEC)</strong> &mdash; eligible Singapore-registered companies can draw on $10,000 of SFEC to cover out-of-pocket costs for staff training.</li> <li><strong>Absentee Payroll</strong> &mdash; employers can claim $4.50 per training hour, capped at $100,000 per enterprise per calendar year, for staff attending during work hours.</li> </ul> <p>The course runs <strong>2 days (16 hours), 9:30am to 6:30pm</strong>, and can be taken in a physical classroom, live via Zoom, or as corporate training at your own premises. Funded seats require at least <strong>75% attendance</strong> and a pass in the written and practical assessments; meet both and you receive a Certificate of Achievement from Tertiary Infotech Academy plus an OpenCert Statement of Achievement from SkillsFuture Singapore. <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-azure-ai-engineer-associate-ai-102-training.html"><strong>Check the next available AI-102 dates and your funding tier &rarr;</strong></a></p> <h2>How to prepare for the exam</h2> <p>A workable four-step approach for a working professional:</p> <ol> <li><strong>Confirm your baseline.</strong> If Azure itself is new to you, sit AI-900 or AZ-900 first rather than fighting two learning curves at once.</li> <li><strong>Take the instructor-led course.</strong> Two days of guided labs against a live Azure subscription is the fastest route through the services you would otherwise never provision on your own.</li> <li><strong>Build one end-to-end project.</strong> The single highest-yield revision exercise is a small RAG application: index a document set with Azure AI Search, ground an Azure OpenAI deployment on it, and add a Document Intelligence step. That one build touches the three heaviest exam domains.</li> <li><strong>Drill with practice questions.</strong> Our <a href="https://exams.tertiaryinfotech.com/practice-exams/microsoft" target="_blank" rel="noopener">free Microsoft practice exam portal</a> covers the Azure and Microsoft certification tracks &mdash; including <a href="https://exams.tertiaryinfotech.com/practice-exams/microsoft/microsoft-ai-900" target="_blank" rel="noopener">AI-900</a> if you are building up to AI-102 &mdash; and is a good way to get used to Microsoft''s question style before exam day.</li> </ol> <p>Where do you go afterwards? The natural continuation is deeper agent and application work on Azure &mdash; see the <a href="https://www.tertiarycourses.com.sg/ai-103-microsoft-certified-azure-ai-apps-and-agents-developer-associate.html">AI-103 Azure AI Apps and Agents Developer Associate</a> course &mdash; or broaden across the platform through our <a href="https://www.tertiarycourses.com.sg/azure-certification-exam-prep.html">Azure certification exam prep</a> range.</p> <h2>Frequently asked questions</h2> <div class="mmd-faq"> <details class="mmd-faq-item"> <summary class="mmd-faq-q">Is AI-102 hard to pass?</summary> <div class="mmd-faq-a"><p>It is a genuine associate-level exam and it expects you to read code. Candidates who already program in Python or C# and have done hands-on labs across Azure AI Search, Azure OpenAI and Document Intelligence generally find it fair. Candidates who revise only by reading service documentation tend to struggle, because the questions are scenario-based and ask which implementation is correct rather than what a service does.</p></div> </details> <details class="mmd-faq-item"> <summary class="mmd-faq-q">Do I need to know machine learning to take AI-102?</summary> <div class="mmd-faq-a"><p>No. AI-102 is about building solutions with Azure''s managed AI services, not about training models from scratch. You need programming ability and cloud familiarity. Training your own models is covered by the Azure data scientist track instead.</p></div> </details> <details class="mmd-faq-item"> <summary class="mmd-faq-q">How much does the AI-102 course cost in Singapore after funding?</summary> <div class="mmd-faq-a"><p>The course fee is $900. Singaporeans below 40 and Singapore PRs receive 50% WSQ funding, and Singaporeans aged 40 and above (MCES) as well as SME-sponsored employees receive 70%. Nett payable including GST is $531 at the baseline tier and $351 at the MCES / SME tier. SkillsFuture Credit can be applied to the balance.</p></div> </details> <details class="mmd-faq-item"> <summary class="mmd-faq-q">Can I use SkillsFuture Credit for the AI-102 course?</summary> <div class="mmd-faq-a"><p>Yes. The course is listed on the SkillsFuture course directory under course code TGS-2023036651, so Singaporeans aged 25 and above can apply SkillsFuture Credit to the out-of-pocket portion after WSQ funding.</p></div> </details> <details class="mmd-faq-item"> <summary class="mmd-faq-q">Does the course fee include the Microsoft exam voucher?</summary> <div class="mmd-faq-a"><p>The WSQ course fee covers the 2-day instructor-led training and the WSQ assessment leading to the Certificate of Achievement and OpenCert. The Microsoft AI-102 certification exam is booked and paid separately through Microsoft''s testing partner. Contact us before enrolling if you would like current exam pricing.</p></div> </details> <details class="mmd-faq-item"> <summary class="mmd-faq-q">Should I take AI-900 or AI-102 first?</summary> <div class="mmd-faq-a"><p>If you do not write code or have never used Azure, take AI-900 first &mdash; it is a fundamentals certification designed to build the vocabulary. If you are already a developer or data engineer, go straight to AI-102; AI-900 is not a prerequisite.</p></div> </details> <details class="mmd-faq-item"> <summary class="mmd-faq-q">What is the attendance requirement for WSQ funding?</summary> <div class="mmd-faq-a"><p>You must attend at least 75% of the course and pass all prescribed assessments. Falling below either threshold means the funding is forfeited and the full fee becomes payable, so plan the two days properly before you enrol.</p></div> </details> </div> <h2>The bottom line</h2> <p>AI-102 sits at a useful intersection: the technology is in genuine demand, the certification is recognised by every employer running a Microsoft estate, and in Singapore the training is subsidised to the point where cost is not a real objection. Two days and $351 nett is an unusually low bar for a credential that moves you from AI user to AI builder.</p> <p><a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-azure-ai-engineer-associate-ai-102-training.html"><strong>View the WSQ Microsoft Certified Azure AI Engineer Associate (AI-102) course, check upcoming dates, and claim up to 70% WSQ funding &rarr;</strong></a></p>', 'Tertiary Infotech Academy', 1, '2025-12-09', 'TGS-2023036651', 'TGS-2023036651', 'manual-skip-no-share', 'Azure AI Engineer Associate (AI-102) Course Singapore | WSQ Funded from $351 | Tertiary Courses', 'Complete guide to the Microsoft Certified Azure AI Engineer Associate (AI-102) certification in Singapore: exam scope, skills measured, salary outlook, and how to claim up to 70% WSQ funding and SkillsFuture Credit on the 2-day AI-102 training course.', 'AI-102, Azure AI Engineer Associate, Microsoft Azure AI certification Singapore, AI-102 course Singapore, Azure OpenAI training, Azure AI Search, WSQ AI course, SkillsFuture AI course, Azure AI Document Intelligence', '2025-12-09 09:00:00', '2025-12-09 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'azure-ai-engineer-associate-ai-102-certification-singapore') x);

-- Tags (core Magento tag vocabulary; status 1 = approved)
INSERT INTO `tag` (`name`, `status`) SELECT 'Microsoft', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Microsoft') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'AI-102', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'AI-102') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'Azure', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Azure') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'WSQ', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'WSQ') x);

SET @post_id := (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'azure-ai-engineer-associate-ai-102-certification-singapore');

INSERT IGNORE INTO `mmd_blog_post_tag` (`post_id`, `tag_id`) SELECT @post_id, `tag_id` FROM `tag` WHERE @post_id IS NOT NULL AND `name` IN ('Microsoft', 'AI-102', 'Azure', 'WSQ');

